          {canSubmitVendorResponse && (
            <div style={{ marginTop: 16, padding: 12, background: "#fff", borderRadius: 8, border: "1px solid #dce6f5" }}>
              <h4 style={{ marginTop: 0 }}>Confirm delivery with vendor</h4>
