                    value={confirmDraft.slotId || ""}
                    onChange={(e) =>
                      setConfirmDrafts((prev) => ({
                        ...prev,
                        [selectedOrder.id]: {
                          ...prev[selectedOrder.id],
                          slotId: e.target.value,
